+// TestEffectOfBinaryAndModeOnlyChanges pins changed-file totals without textual line changes.
+func TestEffectOfBinaryAndModeOnlyChanges(t *testing.T) {
+	t.Parallel()
+	for _, kind := range []string{"binary", "mode-only"} {
+		t.Run(kind, func(t *testing.T) {
+			r := newEdgeRepo(t)
+			if kind == "binary" {
+				r.write("app.txt", "\x00before")
+			} else {
+				r.write("app.txt", "unchanged\n")
+			}
+			start := r.commit("before", nil)
+			first := r.git("rev-parse", start+"^{tree}")
+			if kind == "binary" {
+				r.write("app.txt", "\x00after")
+				r.commit("binary repair", nil)
+			} else {
+				r.commit("mode repair", func() { r.git("update-index", "--chmod=+x", "app.txt") })
+			}
+			final := r.git("rev-parse", "HEAD^{tree}")
+			wantStat := "0\t0\tapp.txt"
+			if kind == "binary" {
+				wantStat = "-\t-\tapp.txt"
+			}
+			if got := r.git("diff", "--numstat", "--no-renames", first, final, "--"); got != wantStat {
+				t.Fatalf("fixture numstat = %q, want %q", got, wantStat)
+			}
+			c := Candidate{Root: r.root, Repo: gitpkg.New(r.root, nil), Start: start}
+			effect := effectOf(c, first, Result{Pass: verify.Pass{Tree: final}}, nil, nil)
+			got := [3]any{deref(effect.FilesChanged), deref(effect.LinesAdded), deref(effect.LinesDeleted)}
+			if got != [3]any{1, 0, 0} {
+				t.Fatalf("effect totals = %v, want [1 0 0]", got)
+			}
+		})
+	}
+}

