+// TestIndependentRepairAccountBinaryAndModeOnlyChanges pins the account of verified non-text repairs.
+func TestIndependentRepairAccountBinaryAndModeOnlyChanges(t *testing.T) {
+	t.Parallel()
+	for _, kind := range []string{"binary", "mode-only"} {
+		t.Run(kind, func(t *testing.T) {
+			in, h := newReview(t)
+			root := in.Candidate.Root
+			git(t, root, nil, "config", "core.filemode", "true")
+			if kind == "binary" {
+				writeFile(t, filepath.Join(root, "app.txt"), "\x00before")
+			}
+			first, err := in.Candidate.Repo.Tree(in.Candidate.Start, nil)
+			if err != nil {
+				t.Fatal(err)
+			}
+			in.Candidate.Tree = first
+			in.Evidence.Pass.Tree = first
+			if kind == "binary" {
+				writeFile(t, filepath.Join(root, "app.txt"), "\x00after")
+			} else if err := os.Chmod(filepath.Join(root, "app.txt"), 0755); err != nil {
+				t.Fatal(err)
+			}
+			final, err := in.Candidate.Repo.Tree(in.Candidate.Start, nil)
+			if err != nil {
+				t.Fatal(err)
+			}
+			wantStat := "0\t0\tapp.txt"
+			if kind == "binary" {
+				wantStat = "-\t-\tapp.txt"
+			}
+			stat, err := in.Candidate.Repo.OK("diff", "--numstat", "--no-renames", first, final, "--")
+			if err != nil || strings.TrimSpace(stat) != wantStat {
+				t.Fatalf("fixture numstat = %q, %v, want %q", stat, err, wantStat)
+			}
+			h.answers = []*provider.Response{submitReview(`{"verdict":"approve","findings":[]}`), submitReview(`{"verdict":"approve","findings":[]}`)}
+			h.verifies = []verify.Pass{{N: 2, Clean: true, Green: true, Tree: final}}
+			res, err := (review.Independent{}).Review(context.Background(), in, h)
+			if err != nil {
+				t.Fatal(err)
+			}
+			if res.Account == nil {
+				t.Fatal("repair has no account")
+			}
+			effect := res.Account.Effect
+			if effect.FilesChanged == nil || effect.LinesAdded == nil || effect.LinesDeleted == nil {
+				t.Fatalf("unknown effect totals: %+v", effect)
+			}
+			deepEq(t, "non-text repair totals", []int{*effect.FilesChanged, *effect.LinesAdded, *effect.LinesDeleted}, []int{1, 0, 0})
+			eq(t, "non-text repair rounds", res.Account.RepairRounds, 1)
+			eq(t, "non-text repair first tree", effect.FirstTree, first)
+			eq(t, "non-text repair final tree", effect.FinalTree, final)
+		})
+	}
+}

